from pathlib import Path
from datetime import datetime
import base64
import shutil
import py_compile

ROOT = Path.cwd()
TARGETS = [
    ROOT / "app_v2.py",
    ROOT / "src/master/jobs.py",
]

missing = [str(p) for p in TARGETS if not p.exists()]
if missing:
    print("エラー：clinic-list-filter-complete フォルダで実行してください。")
    print("見つからないファイル:")
    for p in missing:
        print(" -", p)
    raise SystemExit(1)

stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
backup = ROOT / ("code_backup_research_reset_" + stamp)
backup.mkdir(parents=True, exist_ok=False)

for p in TARGETS:
    rel = p.relative_to(ROOT)
    dst = backup / rel
    dst.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(p, dst)

PAYLOADS = {
    "app_v2.py": '',
    "src/master/jobs.py": '',
}

try:
    for rel, encoded in PAYLOADS.items():
        path = ROOT / rel
        path.write_bytes(base64.b64decode(encoded))

    py_compile.compile(str(ROOT / "app_v2.py"), doraise=True)
    py_compile.compile(str(ROOT / "src/master/jobs.py"), doraise=True)

except Exception as e:
    print("適用中にエラーが発生したため、バックアップから戻します。")
    for p in TARGETS:
        rel = p.relative_to(ROOT)
        src = backup / rel
        if src.exists():
            shutil.copy2(src, p)
    print("エラー:", repr(e))
    raise SystemExit(1)

print("修正しました。")
print("・自動情報収集に『この調査をリセット』ボタンを追加しました。")
print("・実行中の調査件数は開始時点で固定されることを画面に表示します。")
print("・例：30件で開始した調査は、途中で医院数を50に変更しても30件のままです。")
print("・やり直す場合は『一時停止 → 停止完了 → この調査をリセット → 医院数50 → 自動調査を開始』です。")
print("・リセットするのは調査ジョブの進捗表示だけです。")
print("・保存済みHP調査結果、Google Maps取込結果、UUID、Comdesk元データ、月間検索使用数は削除しません。")
print("バックアップ:", backup.name)
